window.docContents[254].resolve({"/Elementary-Functions/___4___38-Inverse-Hyperbolic-Functions___-Further-Properties/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___38-Inverse-Hyperbolic-Functions___-Further-Properties--___4___38-Inverse-Hyperbolic-Functions___-Further-Properties--Derivatives-and-addition-formulas":{"contents":"E9–E14 use principal square roots and explicit complements of the principal\nlogarithmic branch cuts, in addition to branch-point and pole hypotheses.\nE15–E19 are\nmultivalued addition correspondences: each square root may be either value,\nand each displayed sign gives the corresponding value relation.  The Lean\nAPI uses explicit sqrtValue and inverse-value predicates rather than\nfalsely identifying a principal logarithm with every multivalued value.\n\nDirect source links: E9, E10, E11, E12, E13, E14, E15, E16, E17, E18, and E19.\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.38 Inverse Hyperbolic Functions: Further Properties\u0009§4.38 Inverse Hyperbolic Functions: Further Properties","header":"Derivatives and addition formulas","id":"/Elementary-Functions/___4___38-Inverse-Hyperbolic-Functions___-Further-Properties/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___38-Inverse-Hyperbolic-Functions___-Further-Properties--___4___38-Inverse-Hyperbolic-Functions___-Further-Properties--Derivatives-and-addition-formulas"}});